/**
 * Register motion value resolver
 * If the resolver does not have all necessary methods to resolve the value,
 * the original motion helper method ar. Used.
 *
 * As a norm, you need usually to overwrite only:
 *  - getStartValue
 *  - setStartValue
 *  - getMiddleValue
 *  - setMiddleValue
 *  - getEndValue
 *  - setEndValue.
 *
 * @param {string} name
 * @param {{
 *  merge?,
 *  setEndMiddle?,
 *  getStartLimit?,
 *  setEndValue?,
 *  getStartValue?,
 *  setStartMiddle?,
 *  setMiddleValue?,
 *  getEndMiddle?,
 *  setEndLimit?,
 *  getDefaultValue?,
 *  getEndLimit?,
 *  getMiddleValue?,
 *  getEndValue?,
 *  setStartLimit?,
 *  setStartValue?,
 *  getStartMiddle?
 * }} resolver
 */
export declare const add: (name: any, resolver: any) => void;
/**
 * Return a motion value resolver object with all motion helper methods
 * If the resolver does not have all necessary methods to resolve the value,
 * the original motion helper method ar. Used.
 *
 * @param name
 * @returns {{
 *  merge,
 *  setEndMiddle,
 *  getStartLimit,
 *  setEndValue,
 *  getStartValue,
 *  setStartMiddle,
 *  setMiddleValue,
 *  getEndMiddle,
 *  setEndLimit,
 *  getDefaultValue,
 *  getEndLimit,
 *  getMiddleValue,
 *  getEndValue,
 *  setStartLimit,
 *  setStartValue,
 *  getStartMiddle
 * }}
 */
export declare const get: (name: any) => any;
